  // ── L10.T2.3 — Year-end adjustments (sole trader) ─────────────────────────
  "ACC.G10.T2.ADJUSTMENTS.A1": [
    mc("G10.ADJUSTMENTS.01", "Depreciation is…", ["The spreading of an asset's cost over its useful life", "An increase in an asset's value", "Cash paid to the owner", "A type of income"], "The spreading of an asset's cost over its useful life", "Depreciation allocates cost to the periods that use the asset.", ["ERR_ACC_DEPRECIATION"], 1),
    mc("G10.ADJUSTMENTS.02", "An expense owing but not yet paid at year-end is…", ["An accrued expense", "A prepaid expense", "Income received in advance", "A fixed asset"], "An accrued expense", "Accrued expenses are owing at year-end.", ["ERR_ACC_ACCRUED_EXP"], 1),
    mc("G10.ADJUSTMENTS.03", "An expense paid in advance for next year is…", ["A prepaid expense", "An accrued expense", "Accrued income", "A bad debt"], "A prepaid expense", "Prepaid expenses are paid before the period they cover.", ["ERR_ACC_PREPAID"], 1),
    cloze("G10.ADJUSTMENTS.04", "Income earned but not yet received at year-end is ______ income.", ["accrued", "deferred", "prepaid", "received"], "accrued", "Accrued income is earned but still receivable.", ["ERR_ACC_ACCRUED_INC"], 1),
    tf("G10.ADJUSTMENTS.05", "A trading stock deficit means there is less stock on hand than the records show.", true, "A deficit is a shortage versus the recorded amount.", ["ERR_ACC_STOCK_DEFICIT"], 1),
    mc("G10.ADJUSTMENTS.06", "Consumable stores still on hand at year-end are treated as…", ["An asset (not yet used)", "An expense already used", "Income", "A liability"], "An asset (not yet used)", "Unused consumables are an asset at year-end.", ["ERR_ACC_CONSUMABLES"], 1),
    eq("G10.ADJUSTMENTS.07", "Depreciation is written off on equipment at year-end.", "-", "-", "0", "The asset's carrying value falls; depreciation is an expense reducing equity.", ["ERR_ACC_EQUATION"], 2),
    eq("G10.ADJUSTMENTS.08", "A trading stock deficit is found at year-end.", "-", "-", "0", "Stock (asset) falls; the loss reduces owner's equity.", ["ERR_ACC_EQUATION"], 2),
    eq("G10.ADJUSTMENTS.09", "Record telephone expense still owing (accrued) at year-end.", "0", "-", "+", "The extra expense reduces equity; the amount owing is a liability.", ["ERR_ACC_EQUATION"], 2),
    eq("G10.ADJUSTMENTS.10", "Adjust for rent income received in advance at year-end.", "0", "-", "+", "Income earned is reduced now (equity down) and the amount owed to the tenant is a liability.", ["ERR_ACC_EQUATION"], 2),
    eq("G10.ADJUSTMENTS.11", "Adjust for insurance prepaid (part belongs to next year).", "+", "+", "0", "A prepaid asset is created and the expense is reduced, increasing equity.", ["ERR_ACC_EQUATION"], 2),
    eq("G10.ADJUSTMENTS.12", "Record commission income earned but not yet received (accrued income).", "+", "+", "0", "Accrued income is an asset; the income increases equity.", ["ERR_ACC_EQUATION"], 2),
    mc("G10.ADJUSTMENTS.13", "Writing off an additional bad debt at year-end will…", ["Decrease debtors and decrease profit", "Increase debtors and profit", "Increase liabilities", "Have no effect"], "Decrease debtors and decrease profit", "The debtor falls and the expense reduces profit.", ["ERR_ACC_BADDEBT"], 2),
    sort("G10.ADJUSTMENTS.14", "Sort each adjustment by whether it creates an asset or a liability at year-end.", [["asset", "Creates an asset"], ["liab", "Creates a liability"]], [["i1", "Prepaid expenses", "asset"], ["i2", "Accrued income", "asset"], ["i3", "Accrued expenses", "liab"], ["i4", "Income received in advance", "liab"]], "Prepaid expenses and accrued income are assets; accrued expenses and income in advance are liabilities.", ["ERR_ACC_ADJ_CLASSIFY"], 2),
    cloze("G10.ADJUSTMENTS.15", "Stock that is short compared with the records is a trading stock ______.", ["deficit", "surplus", "profit", "asset"], "deficit", "A shortage is a deficit; an excess is a surplus.", ["ERR_ACC_STOCK_DEFICIT"], 2),
    mc("G10.ADJUSTMENTS.16", "Depreciation on the diminishing-balance method is calculated on the…", ["Carrying (book) value", "Original cost only", "Selling price", "Replacement cost"], "Carrying (book) value", "Diminishing balance uses the reducing book value.", ["ERR_ACC_DEPRECIATION_METHOD"], 2),
    mc("G10.ADJUSTMENTS.17", "Depreciation on the cost (straight-line) method is calculated on the…", ["Original cost", "Carrying value", "Market value", "Insured value"], "Original cost", "Straight-line uses the original cost each year.", ["ERR_ACC_DEPRECIATION_METHOD"], 2),
    mc("G10.ADJUSTMENTS.18", "Bad debts recovered (a previously written-off debt now paid) is treated as…", ["Income", "An expense", "A fixed asset", "Capital"], "Income", "Recovering a written-off debt is income.", ["ERR_ACC_BADDEBT_RECOVERED"], 3),
    eq("G10.ADJUSTMENTS.19", "Record consumable stores still on hand at year-end (the adjustment).", "+", "+", "0", "An asset is created for the unused stores and the expense is reduced, raising equity.", ["ERR_ACC_EQUATION"], 3),
    mc("G10.ADJUSTMENTS.20", "Why are year-end adjustments necessary?", ["To match income and expenses to the correct period", "To increase the bank balance", "To avoid VAT", "To reduce the number of debtors"], "To match income and expenses to the correct period", "Adjustments apply the matching principle.", ["ERR_ACC_MATCHING"], 3),
  ],

